situation_event = {
	id = machine_age.3325
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		owner = { #Check how many pops are still alive
			export_trigger_value_to_variable = {
				trigger = count_owned_pop_amount
				parameters = {
					limit = {
						has_trait = trait_pathogenic_genes
					}
				}
				variable = remaining_synth_fert_pops_month_check
			}
		}
		if = { #Update the situation pace in case of discrepancy
			limit = {
				owner = {
					check_variable_arithmetic = {
						which = remaining_synth_fert_pops
						subtract = remaining_synth_fert_pops_month_check
						value != 0
					}
				}
			}
			add_situation_progress = owner.value:num_synth_fert_check_the_dead
			owner = {
				set_variable = {
					which = remaining_synth_fert_pops
					value = remaining_synth_fert_pops_month_check
				}
			}
		}

		# Update the ID repository
		owner = {
			add_variable = {
				which = num_dead_identities
				value = value:num_synth_fert_upload_per_month
			}
			subtract_variable = {
				which = remaining_synth_fert_pops
				value = value:num_synth_fert_upload_per_month
			}

			while = {
				count = value:num_synth_fert_upload_per_month
				weighted_random_owned_pop_group = {
					limit = {
						has_trait = trait_pathogenic_genes
					}
					kill_pop_group = {
						pop_group = this
						amount = 1
					}
				}
			}
		}
	}
}

situation_event = {
